using namespace teserra;

namespace {

constexpr int kFirstChar = 32;
constexpr int kCharCount = 95; // printable ASCII
constexpr f32 kBitmapPx = 32.0F; // bake size of the single-bake bitmap atlas
constexpr f64 kMsdfPx = 32.0;     // pixels per em in the MSDF atlas
constexpr f64 kMsdfRange = 4.0;   // distance range in atlas pixels; msdf.frag's kPixelRange
constexpr UVec2 kWindowSize{1600, 1000};
constexpr std::array<f32, 7> kSizes{10, 14, 20, 32, 56, 96, 160};
constexpr std::string_view kText = "The quick brown fox jumps over the lazy dog 0123456789 (){}[] @#&%";

// A glyph in an atlas: its UV rectangle, its quad relative to the pen in ems (y down from the baseline),
// and the advance in ems.
struct Glyph {
    f32 u0 = 0, v0 = 0, u1 = 0, v1 = 0;
    f32 left = 0, top = 0, right = 0, bottom = 0;
    f32 advance = 0;
    bool visible = false;
};

using GlyphTable = std::array<Glyph, kCharCount>;

struct Atlas {
    u32 size = 1024;
    std::vector<std::byte> rgba; // size x size
    // One table for an atlas that scales; one per kSizes entry for bitmaps baked per size.
    std::vector<GlyphTable> tables;
    f64 buildMilliseconds = 0;
    UVec2 used{}; // the area the glyphs occupy
};

std::optional<std::vector<unsigned char>> readFile(const std::string& path) {
    std::ifstream file(path, std::ios::binary);
    if (!file) {
        return std::nullopt;
    }
    return std::vector<unsigned char>(std::istreambuf_iterator<char>(file), {});
}

// Coverage in the alpha channel: one bake at kBitmapPx with 2x2 oversampling, or one bake per size in kSizes
// (2x1 oversampling up to 32 px for subpixel placement, none above).
Atlas buildBitmapAtlas(const std::vector<unsigned char>& ttf, bool perSize) {
    const auto start = std::chrono::steady_clock::now();
    Atlas atlas;
    atlas.size = perSize ? 2048 : 1024;
    std::vector<unsigned char> coverage(usize{atlas.size} * atlas.size);
    stbtt_pack_context context{};
    stbtt_PackBegin(&context, coverage.data(), static_cast<int>(atlas.size), static_cast<int>(atlas.size), 0, 1,
                    nullptr);
    std::vector<f32> bakes = perSize ? std::vector<f32>(kSizes.begin(), kSizes.end()) : std::vector<f32>{kBitmapPx};
    for (const f32 bake : bakes) {
        if (perSize) {
            stbtt_PackSetOversampling(&context, bake <= 32.0F ? 2 : 1, 1);
        } else {
            stbtt_PackSetOversampling(&context, 2, 2);
        }
        std::array<stbtt_packedchar, kCharCount> packed{};
        // STBTT_POINT_SIZE: `bake` pixels per em, as the MSDF atlas; a plain size would be the ascent-to-descent
        // height, about a third smaller for most fonts.
        if (stbtt_PackFontRange(&context, ttf.data(), 0, STBTT_POINT_SIZE(bake), kFirstChar, kCharCount,
                                packed.data()) == 0) {
            TESERRA_LOG_WARN(LogCategory::App, "The {} px bake does not fit in the {} px atlas", bake, atlas.size);
        }
        GlyphTable& table = atlas.tables.emplace_back();
        const auto size = static_cast<f32>(atlas.size);
        for (int i = 0; i < kCharCount; ++i) {
            const stbtt_packedchar& c = packed[static_cast<usize>(i)];
            table[static_cast<usize>(i)] = {
                .u0 = c.x0 / size, .v0 = c.y0 / size, .u1 = c.x1 / size, .v1 = c.y1 / size,
                .left = c.xoff / bake, .top = c.yoff / bake, .right = c.xoff2 / bake, .bottom = c.yoff2 / bake,
                .advance = c.xadvance / bake, .visible = c.x1 > c.x0,
            };
            atlas.used.x = std::max<u32>(atlas.used.x, c.x1);
            atlas.used.y = std::max<u32>(atlas.used.y, c.y1);
        }
    }
    stbtt_PackEnd(&context);

    atlas.rgba.resize(coverage.size() * 4);
    for (usize i = 0; i < coverage.size(); ++i) {
        atlas.rgba[i * 4 + 0] = std::byte{255};
        atlas.rgba[i * 4 + 1] = std::byte{255};
        atlas.rgba[i * 4 + 2] = std::byte{255};
        atlas.rgba[i * 4 + 3] = std::byte{coverage[i]};
    }
    atlas.buildMilliseconds =
        std::chrono::duration<f64, std::milli>(std::chrono::steady_clock::now() - start).count();
    return atlas;
}

// The glyph's outline as an msdfgen shape, in font units (y up).
msdfgen::Shape glyphShape(const stbtt_fontinfo& font, int glyph) {
    stbtt_vertex* vertices = nullptr;
    const int count = stbtt_GetGlyphShape(&font, glyph, &vertices);
    msdfgen::Shape shape;
    msdfgen::Contour* contour = nullptr;
    msdfgen::Point2 last;
    for (int i = 0; i < count; ++i) {
        const stbtt_vertex& v = vertices[i];
        const msdfgen::Point2 point(v.x, v.y);
        switch (v.type) {
            case STBTT_vmove:
                contour = &shape.addContour();
                break;
            case STBTT_vline:
                contour->addEdge(msdfgen::EdgeHolder(last, point));
                break;
            case STBTT_vcurve:
                contour->addEdge(msdfgen::EdgeHolder(last, msdfgen::Point2(v.cx, v.cy), point));
                break;
            case STBTT_vcubic:
                contour->addEdge(msdfgen::EdgeHolder(last, msdfgen::Point2(v.cx, v.cy),
                                                     msdfgen::Point2(v.cx1, v.cy1), point));
                break;
            default:
                break;
        }
        last = point;
    }
    stbtt_FreeShape(&font, vertices);
    return shape;
}

// MSDF at kMsdfPx per em with a kMsdfRange-pixel distance range, packed in shelves.
Atlas buildMsdfAtlas(const std::vector<unsigned char>& ttf) {
    const auto start = std::chrono::steady_clock::now();
    stbtt_fontinfo font{};
    stbtt_InitFont(&font, ttf.data(), stbtt_GetFontOffsetForIndex(ttf.data(), 0));
    const f64 unitsPerEm = 1.0 / stbtt_ScaleForMappingEmToPixels(&font, 1.0F);
    const f64 scale = kMsdfPx / unitsPerEm; // atlas pixels per font unit
    const f64 padding = kMsdfRange / scale;  // in font units

    constexpr u32 kAtlasSize = 1024;
    Atlas atlas;
    atlas.rgba.assign(usize{kAtlasSize} * kAtlasSize * 4, std::byte{0});
    GlyphTable& table = atlas.tables.emplace_back();
    u32 shelfX = 0;
    u32 shelfY = 0;
    u32 shelfHeight = 0;
    for (int i = 0; i < kCharCount; ++i) {
        Glyph& glyph = table[static_cast<usize>(i)];
        const int index = stbtt_FindGlyphIndex(&font, kFirstChar + i);
        int advance = 0;
        int bearing = 0;
        stbtt_GetGlyphHMetrics(&font, index, &advance, &bearing);
        glyph.advance = static_cast<f32>(advance / unitsPerEm);

        msdfgen::Shape shape = glyphShape(font, index);
        if (shape.contours.empty()) {
            continue;
        }
        shape.normalize();
        shape.orientContours();
        msdfgen::edgeColoringSimple(shape, 3.0);
        const msdfgen::Shape::Bounds bounds = shape.getBounds();
        const auto width = static_cast<u32>(std::ceil((bounds.r - bounds.l + 2 * padding) * scale));
        const auto height = static_cast<u32>(std::ceil((bounds.t - bounds.b + 2 * padding) * scale));
        // A gutter of one empty texel keeps linear filtering from reading the neighbour's distances.
        if (shelfX + width + 1 > kAtlasSize) {
            shelfX = 0;
            shelfY += shelfHeight + 1;
            shelfHeight = 0;
        }
        const msdfgen::Vector2 translate(-bounds.l + padding, -bounds.b + padding);
        msdfgen::Bitmap<float, 3> msdf(static_cast<int>(width), static_cast<int>(height));
        msdfgen::generateMSDF(msdf, shape,
                              msdfgen::SDFTransformation(msdfgen::Projection(scale, translate),
                                                         msdfgen::Range(kMsdfRange / scale)));
        // msdfgen's rows go up from the bottom; the atlas's go down from the top.
        for (u32 y = 0; y < height; ++y) {
            for (u32 x = 0; x < width; ++x) {
                const float* pixel = msdf(static_cast<int>(x), static_cast<int>(height - 1 - y));
                std::byte* out = &atlas.rgba[((usize{shelfY + y} * kAtlasSize) + shelfX + x) * 4];
                for (int c = 0; c < 3; ++c) {
                    out[c] = std::byte{static_cast<unsigned char>(
                        std::clamp(std::lround(pixel[c] * 255.0F), 0L, 255L))};
                }
                out[3] = std::byte{255};
            }
        }
        const f32 size = kAtlasSize;
        // The bitmap covers font units [-translate, -translate + size / scale], y up.
        const f64 left = -translate.x;
        const f64 bottom = -translate.y;
        glyph = {
            .u0 = static_cast<f32>(shelfX) / size, .v0 = static_cast<f32>(shelfY) / size,
            .u1 = static_cast<f32>(shelfX + width) / size, .v1 = static_cast<f32>(shelfY + height) / size,
            .left = static_cast<f32>(left / unitsPerEm),
            .top = static_cast<f32>(-(bottom + height / scale) / unitsPerEm),
            .right = static_cast<f32>((left + width / scale) / unitsPerEm),
            .bottom = static_cast<f32>(-bottom / unitsPerEm),
            .advance = glyph.advance, .visible = true,
        };
        atlas.used.x = std::max(atlas.used.x, shelfX + width);
        atlas.used.y = std::max(atlas.used.y, shelfY + height);
        shelfX += width + 1;
        shelfHeight = std::max(shelfHeight, height);
    }
    atlas.buildMilliseconds =
        std::chrono::duration<f64, std::milli>(std::chrono::steady_clock::now() - start).count();
    return atlas;
}

struct Vertex {
    Vec2 position;
    Vec2 uv;
};

// The quads of `text` at `pixels` per em with its baseline at `pen` (window pixels, y down).
void layout(const GlyphTable& glyphs, std::string_view text, Vec2 pen, f32 pixels, std::vector<Vertex>& out) {
    const auto ndc = [](f32 x, f32 y) {
        return Vec2{x / static_cast<f32>(kWindowSize.x) * 2.0F - 1.0F,
                    1.0F - y / static_cast<f32>(kWindowSize.y) * 2.0F};
    };
    for (const char c : text) {
        const int index = c - kFirstChar;
        if (index < 0 || index >= kCharCount) {
            continue;
        }
        const Glyph& g = glyphs[static_cast<usize>(index)];
        if (g.visible) {
            const f32 x0 = pen.x + g.left * pixels;
            const f32 x1 = pen.x + g.right * pixels;
            const f32 y0 = pen.y + g.top * pixels;
            const f32 y1 = pen.y + g.bottom * pixels;
            const Vertex topLeft{ndc(x0, y0), {g.u0, g.v0}};
            const Vertex bottomLeft{ndc(x0, y1), {g.u0, g.v1}};
            const Vertex bottomRight{ndc(x1, y1), {g.u1, g.v1}};
            const Vertex topRight{ndc(x1, y0), {g.u1, g.v0}};
            out.insert(out.end(), {topLeft, bottomLeft, bottomRight, topLeft, bottomRight, topRight});
        }
        pen.x += g.advance * pixels;
    }
}

std::vector<Vertex> buildLines(const Atlas& atlas, f32 firstBaseline) {
    std::vector<Vertex> vertices;
    f32 baseline = firstBaseline;
    for (usize i = 0; i < kSizes.size(); ++i) {
        const f32 size = kSizes[i];
        baseline = std::round(baseline + size);
        const std::string line = std::to_string(static_cast<int>(size)) + "px " + std::string(kText);
        layout(atlas.tables[atlas.tables.size() == 1 ? 0 : i], line, {8.0F, baseline}, size, vertices);
        baseline += size * 0.25F;
    }
    return vertices;
}

class TextSpike {
public:
    explicit TextSpike(rhi::Device& device)
        : m_device(device) {}

    [[nodiscard]] Result<void> create(const Atlas& bitmap, const Atlas& msdf, rhi::Format targetFormat) {
        TESERRA_TRY_ASSIGN(m_vertex, m_device.createShaderModule({.stage = rhi::ShaderStage::Vertex,
                                                                  .blob = examples::shaders::kTextVert}));
        TESERRA_TRY_ASSIGN(m_bitmapFragment,
                           m_device.createShaderModule(
                               {.stage = rhi::ShaderStage::Fragment, .blob = examples::shaders::kBitmapFrag}));
        TESERRA_TRY_ASSIGN(m_msdfFragment,
                           m_device.createShaderModule(
                               {.stage = rhi::ShaderStage::Fragment, .blob = examples::shaders::kMsdfFrag}));
        constexpr std::array kEntries{rhi::BindGroupLayoutEntry{
            .binding = 0, .type = rhi::BindingType::SampledTexture, .visibility = rhi::ShaderStage::Fragment}};
        TESERRA_TRY_ASSIGN(m_groupLayout, m_device.createBindGroupLayout({.entries = kEntries}));
        const std::array groups{rhi::BindGroupLayoutHandle{}, rhi::BindGroupLayoutHandle{}, m_groupLayout};
        TESERRA_TRY_ASSIGN(m_layout, m_device.createPipelineLayout({.groups = groups}));
        TESERRA_TRY_ASSIGN(m_sampler, m_device.createSampler({.debugName = "Linear"}));
        TESERRA_TRY_ASSIGN(m_bitmap, makeHalf(bitmap, m_bitmapFragment, 0.0F, targetFormat, "Bitmap"));
        TESERRA_TRY_ASSIGN(m_msdf, makeHalf(msdf, m_msdfFragment, static_cast<f32>(kWindowSize.y) * 0.5F,
                                            targetFormat, "MSDF"));
        return {};
    }

    void record(rhi::CommandList& cmd, rhi::TextureHandle target) const {
        cmd.beginRenderPass({.colorAttachments = {{.texture = target,
                                                   .loadOp = rhi::LoadOp::Clear,
                                                   .clearColor = {0.08F, 0.08F, 0.1F, 1.0F}}}});
        cmd.setViewport({.width = static_cast<f32>(kWindowSize.x), .height = static_cast<f32>(kWindowSize.y)});
        for (const Half* half : {&m_bitmap, &m_msdf}) {
            cmd.bindPipeline(half->pipeline);
            cmd.bindGroup(rhi::kMaterialGroup, half->group);
            cmd.bindVertexBuffer(0, half->vertices);
            cmd.draw({.vertexCount = half->vertexCount});
        }
        cmd.endRenderPass();
    }

private:
    struct Half {
        rhi::TextureHandle atlas;
        rhi::BindGroupHandle group;
        rhi::GraphicsPipelineHandle pipeline;
        rhi::BufferHandle vertices;
        u32 vertexCount = 0;
    };

    Result<Half> makeHalf(const Atlas& atlas, rhi::ShaderModuleHandle fragment, f32 top, rhi::Format format,
                          std::string_view name) {
        Half half;
        // The bitmap's coverage and the MSDF's distances are data, not colors: Unorm, not sRGB.
        TESERRA_TRY_ASSIGN(half.atlas, m_device.createTexture({.format = rhi::Format::Rgba8Unorm,
                                                               .width = atlas.size,
                                                               .height = atlas.size,
                                                               .usage = rhi::TextureUsage::Sampled |
                                                                        rhi::TextureUsage::CopyDst,
                                                               .debugName = name}));
        m_device.writeTexture(half.atlas, {.width = atlas.size, .height = atlas.size}, atlas.rgba);
        const std::array entries{rhi::BindGroupEntry{.binding = 0, .texture = half.atlas, .sampler = m_sampler}};
        TESERRA_TRY_ASSIGN(half.group, m_device.createBindGroup({.layout = m_groupLayout, .entries = entries}));
        constexpr std::array kBuffers{rhi::VertexBufferLayout{.stride = sizeof(Vertex)}};
        constexpr std::array kAttributes{
            rhi::VertexAttribute{.location = 0, .format = rhi::VertexFormat::Float2, .offset = 0},
            rhi::VertexAttribute{.location = 1, .format = rhi::VertexFormat::Float2, .offset = sizeof(Vec2)},
        };
        TESERRA_TRY_ASSIGN(half.pipeline,
                           m_device.createGraphicsPipeline({
                               .vertexShader = m_vertex,
                               .fragmentShader = fragment,
                               .layout = m_layout,
                               .vertexBuffers = kBuffers,
                               .vertexAttributes = kAttributes,
                               .colorBlend = {{.enabled = true,
                                               .srcColor = rhi::BlendFactor::SrcAlpha,
                                               .dstColor = rhi::BlendFactor::OneMinusSrcAlpha,
                                               .srcAlpha = rhi::BlendFactor::One,
                                               .dstAlpha = rhi::BlendFactor::OneMinusSrcAlpha}},
                               .targets = {.colorFormats = {format}},
                               .debugName = name,
                           }));
        const std::vector<Vertex> vertices = buildLines(atlas, top);
        half.vertexCount = static_cast<u32>(vertices.size());
        TESERRA_TRY_ASSIGN(half.vertices, m_device.createBuffer({.sizeInBytes = vertices.size() * sizeof(Vertex),
                                                                 .usage = rhi::BufferUsage::Vertex |
                                                                          rhi::BufferUsage::CopyDst}));
        m_device.writeBuffer(half.vertices, 0, std::as_bytes(std::span(vertices)));
        return half;
    }

    rhi::Device& m_device;
    rhi::ShaderModuleHandle m_vertex;
    rhi::ShaderModuleHandle m_bitmapFragment;
    rhi::ShaderModuleHandle m_msdfFragment;
    rhi::BindGroupLayoutHandle m_groupLayout;
    rhi::PipelineLayoutHandle m_layout;
    rhi::SamplerHandle m_sampler;
    Half m_bitmap;
    Half m_msdf;
};

// Renders one frame into a texture and writes it as a PNG.
bool screenshot(rhi::Device& device, const TextSpike& spike, rhi::Format format, const std::string& path) {
    const rhi::TextureHandle target = *device.createTexture({.format = format,
                                                             .width = kWindowSize.x,
                                                             .height = kWindowSize.y,
                                                             .usage = rhi::TextureUsage::RenderTarget |
                                                                      rhi::TextureUsage::CopySrc});
    const rhi::BufferHandle readback = *device.createBuffer({.sizeInBytes = u64{kWindowSize.x} * kWindowSize.y * 4,
                                                             .usage = rhi::BufferUsage::CopyDst,
                                                             .memory = rhi::MemoryLocation::Readback});
    device.beginFrame();
    rhi::CommandList& cmd = device.acquireCommandList();
    spike.record(cmd, target);
    cmd.copyTextureToBuffer({.buffer = readback, .texture = target, .width = kWindowSize.x, .height = kWindowSize.y});
    device.submit(cmd);
    device.endFrame();
    device.waitIdle();
    const std::span<std::byte> pixels = device.map(readback);
    const int written = stbi_write_png(path.c_str(), static_cast<int>(kWindowSize.x),
                                       static_cast<int>(kWindowSize.y), 4, pixels.data(),
                                       static_cast<int>(kWindowSize.x * 4));
    // The 10, 14 and 20 px lines of both halves, three times larger with nearest neighbours.
    constexpr u32 kCropWidth = 540;
    constexpr u32 kCropHeight = 58;
    constexpr u32 kZoom = 3;
    std::vector<std::byte> zoom(usize{kCropWidth} * kZoom * kCropHeight * 2 * kZoom * 4);
    for (u32 y = 0; y < kCropHeight * 2 * kZoom; ++y) {
        const u32 sourceRow = y / kZoom < kCropHeight ? y / kZoom : y / kZoom - kCropHeight + kWindowSize.y / 2;
        for (u32 x = 0; x < kCropWidth * kZoom; ++x) {
            std::memcpy(&zoom[(usize{y} * kCropWidth * kZoom + x) * 4],
                        &pixels[(usize{sourceRow} * kWindowSize.x + x / kZoom) * 4], 4);
        }
    }
    const std::string zoomPath = path.substr(0, path.size() - 4) + "-zoom.png";
    stbi_write_png(zoomPath.c_str(), static_cast<int>(kCropWidth * kZoom), static_cast<int>(kCropHeight * 2 * kZoom),
                   4, zoom.data(), static_cast<int>(kCropWidth * kZoom * 4));
    device.destroy(readback);
    device.destroy(target);
    return written != 0;
}

} // namespace

int main(int argc, char** argv) { // NOLINT(bugprone-exception-escape)
    std::string fontPath = "C:/Windows/Fonts/segoeui.ttf";
    std::string screenshotPath;
    bool singleBake = false;
    for (int i = 1; i < argc; ++i) {
        if (std::string_view(argv[i]) == "--single-bake") {
            singleBake = true;
        }
    }
    for (int i = 1; i + 1 < argc; ++i) {
        if (std::string_view(argv[i]) == "--font") {
            fontPath = argv[++i];
        } else if (std::string_view(argv[i]) == "--screenshot") {
            screenshotPath = argv[++i];
        }
    }
    engine::App app{{.title = "Teserra: text spike (top: stb_truetype bitmap, bottom: msdfgen MSDF)",
                     .windowSize = kWindowSize,
                     .resizable = false,
                     .windowVisible = screenshotPath.empty(),
                     .args = {argc, argv}}};
    if (!app.isInitialized()) {
        log::flush();
        return 1;
    }
    const std::optional<std::vector<unsigned char>> ttf = readFile(fontPath);
    if (!ttf) {
        TESERRA_LOG_ERROR(LogCategory::App, "Could not read {}", fontPath);
        log::flush();
        return 1;
    }
    const Atlas bitmap = buildBitmapAtlas(*ttf, !singleBake);
    const Atlas msdf = buildMsdfAtlas(*ttf);
    TESERRA_LOG_INFO(LogCategory::App, "Font {} ({} KiB)", fontPath, ttf->size() / 1024);
    TESERRA_LOG_INFO(LogCategory::App, "Bitmap atlas ({} bakes): {:.2f} ms, glyphs in {}x{} of {}x{}",
                     bitmap.tables.size(), bitmap.buildMilliseconds, bitmap.used.x, bitmap.used.y, bitmap.size,
                     bitmap.size);
    TESERRA_LOG_INFO(LogCategory::App, "MSDF atlas: {:.2f} ms, glyphs in {}x{} of {}x{}", msdf.buildMilliseconds,
                     msdf.used.x, msdf.used.y, msdf.size, msdf.size);

    const rhi::Format format = app.device().swapchain()->format();
    TextSpike spike(app.device());
    if (const Result<void> created = spike.create(bitmap, msdf, format); !created) {
        TESERRA_LOG_ERROR(LogCategory::App, "Could not create the spike: {}", created.error());
        log::flush();
        return 1;
    }
    if (!screenshotPath.empty()) {
        const bool written = screenshot(app.device(), spike, format, screenshotPath);
        TESERRA_LOG_INFO(LogCategory::App, "Screenshot {}: {}", screenshotPath, written ? "written" : "failed");
        log::flush();
        return written ? 0 : 1;
    }
    const int exitCode = app.run({
        .update =
            [&](engine::App& running, f32 /*deltaSeconds*/) {
                if (running.input().wasPressed(platform::Key::Escape)) {
                    running.quit();
                }
            },
        .render = [&](engine::App& running, rhi::CommandList& commands) { spike.record(commands, running.backbuffer()); },
    });
    log::flush();
    return exitCode;
}
